import type { Vec3 } from '../contracts/math';
import type { SurfaceDescriptor, SurfaceMaterial } from '../courses/types';
import { clamp } from '../physics/helpers';

/** Physics parameters a rolling ball sees while it touches a surface material. */
export interface SurfaceProperties {
  friction: number;
  restitution: number;
  rollingResistance: number;
  slipFactor: number;
}

export const SURFACE_PROPERTIES: Record<SurfaceMaterial, SurfaceProperties> = {
  green: { friction: 0.55, restitution: 0.32, rollingResistance: 0.35, slipFactor: 0.35 },
  rough: { friction: 0.9, restitution: 0.12, rollingResistance: 0.9, slipFactor: 0.3 },
  sand: { friction: 1.1, restitution: 0.08, rollingResistance: 1.2, slipFactor: 0.25 },
  ice: { friction: 0.04, restitution: 0.4, rollingResistance: 0.02, slipFactor: 0.95 },
  wood: { friction: 0.45, restitution: 0.45, rollingResistance: 0.3, slipFactor: 0.5 },
  stone: { friction: 0.6, restitution: 0.4, rollingResistance: 0.35, slipFactor: 0.45 },
  metal: { friction: 0.35, restitution: 0.6, rollingResistance: 0.22, slipFactor: 0.7 },
};

/** Table lookup; per descriptor overrides win, clamped to 0..2 (friction) and 0..1 (restitution). */
export function resolveSurface(
  descriptor: Pick<SurfaceDescriptor, 'material' | 'friction' | 'restitution'>,
): SurfaceProperties {
  const base = SURFACE_PROPERTIES[descriptor.material] ?? SURFACE_PROPERTIES.green;
  const friction = descriptor.friction;
  const restitution = descriptor.restitution;
  return {
    friction:
      typeof friction === 'number' && Number.isFinite(friction) ? clamp(friction, 0, 2) : base.friction,
    restitution:
      typeof restitution === 'number' && Number.isFinite(restitution)
        ? clamp(restitution, 0, 1)
        : base.restitution,
    rollingResistance: base.rollingResistance,
    slipFactor: base.slipFactor,
  };
}

/** Per step rolling damping: horizontal axes only, never flips the sign of the velocity. */
export function applySurfaceDamping(velocity: Vec3, surface: SurfaceProperties, dt: number): Vec3 {
  const step = Number.isFinite(dt) && dt > 0 ? dt : 0;
  const factor = Math.max(0, 1 - surface.rollingResistance * step);
  return { x: velocity.x * factor, y: velocity.y, z: velocity.z * factor };
}

/** Sticky surfaces park the ball earlier than slick ones. */
export function stopsOnSurface(
  speed: number,
  surface: SurfaceProperties,
  stopThreshold: number,
): boolean {
  return speed <= stopThreshold * (1 + surface.rollingResistance);
}
