import { describe, it, expect } from 'vitest';
import type { Vec3 } from '../contracts/math';
import type { SurfaceMaterial } from '../courses/types';
import {
  SURFACE_PROPERTIES,
  applySurfaceDamping,
  resolveSurface,
  stopsOnSurface,
  type SurfaceProperties,
} from './surfaces';
import { vec3 } from './vec';

const MATERIALS: SurfaceMaterial[] = ['green', 'rough', 'sand', 'ice', 'wood', 'stone', 'metal'];

function horizontalSpeed(v: Vec3): number {
  return Math.hypot(v.x, v.z);
}

function dampFor(velocity: Vec3, surface: SurfaceProperties, seconds: number, dt: number): Vec3 {
  let current = velocity;
  const steps = Math.round(seconds / dt);
  for (let i = 0; i < steps; i += 1) {
    current = applySurfaceDamping(current, surface, dt);
  }
  return current;
}

describe('surface friction model', () => {
  it('keeps far more speed on ice than on sand after one second', () => {
    const start = vec3(4, 0, 3);
    const ice = dampFor(start, resolveSurface({ material: 'ice' }), 1, 0.1);
    const sand = dampFor(start, resolveSurface({ material: 'sand' }), 1, 0.1);
    expect(horizontalSpeed(ice)).toBeGreaterThan(4.5);
    expect(horizontalSpeed(sand)).toBeLessThan(2);
    expect(horizontalSpeed(ice)).toBeGreaterThan(horizontalSpeed(sand) * 3);
  });

  it('lets descriptor overrides win over the table and clamps them', () => {
    expect(resolveSurface({ material: 'green' })).toEqual(SURFACE_PROPERTIES.green);
    const loud = resolveSurface({ material: 'ice', friction: 5, restitution: 2 });
    expect(loud.friction).toBe(2);
    expect(loud.restitution).toBe(1);
    expect(loud.rollingResistance).toBe(SURFACE_PROPERTIES.ice.rollingResistance);
    const quiet = resolveSurface({ material: 'sand', friction: -1, restitution: 0.5 });
    expect(quiet.friction).toBe(0);
    expect(quiet.restitution).toBe(0.5);
    expect(quiet.slipFactor).toBe(SURFACE_PROPERTIES.sand.slipFactor);
  });

  it('never damps into negative speed and leaves the vertical axis alone', () => {
    const sand = resolveSurface({ material: 'sand' });
    const start = vec3(3, -2, 4);
    const damped = applySurfaceDamping(start, sand, 10);
    expect(damped.x).toBe(0);
    expect(damped.z).toBe(0);
    expect(damped.y).toBe(-2);
    expect(horizontalSpeed(damped)).toBeGreaterThanOrEqual(0);
    expect(start).toEqual(vec3(3, -2, 4));
    expect(damped).not.toBe(start);
  });

  it('raises the stop threshold with rolling resistance', () => {
    const ice = resolveSurface({ material: 'ice' });
    const sand = resolveSurface({ material: 'sand' });
    expect(stopsOnSurface(0.1, ice, 0.1)).toBe(true);
    expect(stopsOnSurface(0.11, ice, 0.1)).toBe(false);
    expect(stopsOnSurface(0.2, sand, 0.1)).toBe(true);
    expect(stopsOnSurface(0.25, sand, 0.1)).toBe(false);
  });

  it('defines properties for every surface material', () => {
    expect(Object.keys(SURFACE_PROPERTIES).sort()).toEqual([...MATERIALS].sort());
    for (const material of MATERIALS) {
      const props = SURFACE_PROPERTIES[material];
      expect(Number.isFinite(props.friction)).toBe(true);
      expect(props.friction).toBeGreaterThanOrEqual(0);
      expect(props.restitution).toBeGreaterThanOrEqual(0);
      expect(props.restitution).toBeLessThanOrEqual(1);
      expect(props.rollingResistance).toBeGreaterThanOrEqual(0);
      expect(props.slipFactor).toBeGreaterThan(0);
    }
  });
});
